import { readFileSync, writeFileSync } from 'node:fs';
import { ACCEPTED_SCHEMA_VERSIONS, ACTIVITY_IDS, ENGINES, ENGINE_IDS, SCHEMA_VERSION, SEQUENCE_ENGINES } from '../packages/contracts/index.ts';
